<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Facades\Hash;
use Symfony\Component\HttpFoundation\StreamedResponse;

class SystemController extends Controller {
    public function report(Request $r,string $type){$c=$r->user()->company_id;$b=$r->user()->branch_id;$from=$r->date_from?:now()->startOfMonth();$to=$r->date_to?:now();$data=match($type){
        'sales'=>DB::table('sales')->where(['company_id'=>$c,'branch_id'=>$b])->whereBetween('created_at',[$from,$to])->get(),
        'purchases'=>DB::table('purchases')->where(['company_id'=>$c,'branch_id'=>$b])->whereBetween('created_at',[$from,$to])->get(),
        'inventory'=>DB::table('products as p')->join('stocks as s','s.product_id','=','p.id')->where('p.company_id',$c)->select('p.sku','p.name','p.category','s.quantity','p.average_cost','p.sale_price',DB::raw('s.quantity*p.average_cost as valuation'))->get(),
        'profit'=>DB::table('sale_details as d')->join('sales as s','s.id','=','d.sale_id')->where('s.company_id',$c)->where('s.status','paid')->whereBetween('s.created_at',[$from,$to])->selectRaw('SUM(d.total) revenue, SUM(d.quantity*d.historical_unit_cost) cost, SUM(d.total-d.quantity*d.historical_unit_cost) profit')->get(),
        'cash'=>DB::table('cash_sessions')->where(['company_id'=>$c,'branch_id'=>$b])->whereBetween('opened_at',[$from,$to])->get(),
        'expenses'=>DB::table('expenses')->where(['company_id'=>$c,'branch_id'=>$b])->whereBetween('expense_date',[$from,$to])->get(),
        'customers'=>DB::table('customers as c')->leftJoin('sales as s','s.customer_id','=','c.id')->where('c.company_id',$c)->groupBy('c.id')->selectRaw('c.id,c.name,c.document_number,c.phone,COUNT(s.id) purchases,COALESCE(SUM(s.total),0) total')->get(),
        'suppliers'=>DB::table('suppliers as p')->leftJoin('purchases as c','c.supplier_id','=','p.id')->where('p.company_id',$c)->groupBy('p.id')->selectRaw('p.id,p.name,p.document_number,p.phone,COUNT(c.id) purchases,COALESCE(SUM(c.total),0) total')->get(),
        'products'=>DB::table('sale_details as d')->join('sales as s','s.id','=','d.sale_id')->where('s.company_id',$c)->whereBetween('s.created_at',[$from,$to])->groupBy('d.product_id','d.product_name')->selectRaw('d.product_id,d.product_name,SUM(d.quantity) quantity,SUM(d.total) total')->orderByDesc('quantity')->get(),
        'promotions'=>DB::table('promotions as p')->leftJoin('promotion_usages as u','u.promotion_id','=','p.id')->where('p.company_id',$c)->groupBy('p.id')->selectRaw('p.id,p.name,p.type,p.value,p.starts_at,p.ends_at,p.status,COUNT(u.id) applications,COALESCE(SUM(u.discount),0) discount_total')->get(),
        'taxes'=>DB::table('sales')->where('company_id',$c)->whereBetween('created_at',[$from,$to])->selectRaw('SUM(subtotal) subtotal,SUM(tax) tax,SUM(total) total')->get(),
        'ai'=>DB::table('ai_logs')->where('company_id',$c)->whereBetween('created_at',[$from,$to])->select('created_at','feature','model','tokens','cost','status')->get(),
        default=>abort(404,'Reporte no disponible')
    };return response()->json(['success'=>true,'data'=>['type'=>$type,'from'=>(string)$from,'to'=>(string)$to,'rows'=>$data]]);
    }
    public function export(Request $r,string $type){$data=$this->report($r,$type)->getData(true)['data']['rows'];$rows=json_decode(json_encode($data),true);$format=$r->query('format','csv');$base="reporte-{$type}-".now()->format('Ymd-His');if($format==='xlsx'||$format==='xls'){$xml=$this->spreadsheetXml($rows,$type);return response($xml,200,['Content-Type'=>'application/vnd.ms-excel; charset=UTF-8','Content-Disposition'=>"attachment; filename=\"{$base}.xls\""]);}if($format==='pdf'){$pdf=$this->simplePdf("Reporte ".ucfirst($type),$rows);return response($pdf,200,['Content-Type'=>'application/pdf','Content-Disposition'=>"attachment; filename=\"{$base}.pdf\""]);}return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $row)fputcsv($out,array_map(fn($v)=>is_array($v)?json_encode($v):$v,$row));}fclose($out);},"{$base}.csv",['Content-Type'=>'text/csv']);}
    public function schedules(Request $r){return response()->json(['success'=>true,'data'=>DB::table('scheduled_reports')->where('company_id',$r->user()->company_id)->get()]);}
    // Cada historial devuelve nombres legibles (cliente, usuario, producto) en lugar de identificadores internos.
    public function histories(Request $r,string $type){$c=$r->user()->company_id;$b=$r->user()->branch_id;
        $user=fn($q,$a)=>$q->leftJoin('users as u','u.id','=',"$a.user_id");
        $rows=match($type){
            'sales'=>$user(DB::table('sales as s')->leftJoin('customers as c','c.id','=','s.customer_id'),'s')->where(['s.company_id'=>$c,'s.branch_id'=>$b])->select('s.created_at','s.document_type','s.number','c.name as customer_name','u.name as user_name','s.subtotal','s.discount','s.tax','s.total','s.status')->latest('s.created_at')->limit(500)->get(),
            'purchases'=>$user(DB::table('purchases as h')->leftJoin('suppliers as sp','sp.id','=','h.supplier_id'),'h')->where(['h.company_id'=>$c,'h.branch_id'=>$b])->select('h.created_at','h.document_type','h.number','h.invoice_number','sp.name as supplier_name','u.name as user_name','h.subtotal','h.tax','h.freight','h.total','h.status')->latest('h.created_at')->limit(500)->get(),
            'prices'=>$user(DB::table('price_history as h')->join('products as p','p.id','=','h.product_id'),'h')->where('h.company_id',$c)->select('h.created_at','p.name as product_name','h.previous_price','h.new_price','h.reason','u.name as user_name')->latest('h.created_at')->limit(500)->get(),
            'costs'=>$user(DB::table('cost_history as h')->join('products as p','p.id','=','h.product_id'),'h')->where('h.company_id',$c)->select('h.created_at','p.name as product_name','h.previous_cost','h.new_cost','h.source','u.name as user_name')->latest('h.created_at')->limit(500)->get(),
            'stock'=>$user(DB::table('inventory_movements as h')->join('products as p','p.id','=','h.product_id')->leftJoin('warehouses as w','w.id','=','h.warehouse_id'),'h')->where('h.company_id',$c)->select('h.created_at','p.name as product_name','w.name as warehouse_name','h.type','h.quantity','h.previous_stock','h.new_stock','h.document_number','u.name as user_name')->latest('h.created_at')->limit(500)->get(),
            'cash'=>$user(DB::table('cash_movements as m')->join('cash_sessions as s','s.id','=','m.cash_session_id'),'m')->where('s.company_id',$c)->select('m.created_at','m.type','m.amount','m.description','m.reference','u.name as user_name','s.opened_at')->latest('m.created_at')->limit(500)->get(),
            'users'=>$user(DB::table('audit_events as a'),'a')->where('a.company_id',$c)->select('a.created_at','u.name as user_name','a.event','a.entity','a.entity_id','a.ip')->latest('a.created_at')->limit(500)->get(),
            'promotions'=>DB::table('promotions')->where('company_id',$c)->select('name','type','value','starts_at','ends_at','status','created_at')->latest()->get(),
            'orders'=>DB::table('web_orders')->where('company_id',$c)->select('created_at','number','customer_name','customer_phone','total','payment_method','payment_status','status')->latest()->get(),
            default=>abort(404,'Historial no disponible')};
        return response()->json(['success'=>true,'data'=>$rows]);}
    public function schedule(Request $r){$d=$r->validate(['name'=>'required','report_type'=>'required','format'=>'required|in:csv,pdf','frequency'=>'required|in:daily,weekly,monthly','recipients'=>'nullable']);$next=match($d['frequency']){'daily'=>now()->addDay(),'weekly'=>now()->addWeek(),'monthly'=>now()->addMonth()};$id=DB::table('scheduled_reports')->insertGetId($d+['company_id'=>$r->user()->company_id,'user_id'=>$r->user()->id,'active'=>1,'next_run_at'=>$next,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Reporte programado','data'=>['id'=>$id]],201);}
    public function files(Request $r){return response()->json(['success'=>true,'data'=>DB::table('documents')->where('company_id',$r->user()->company_id)->latest()->get()]);}
    public function upload(Request $r){$r->validate(['file'=>'required|file|max:10240']);$file=$r->file('file');$path=$file->store('documents/'.$r->user()->company_id);$id=DB::table('documents')->insertGetId(['company_id'=>$r->user()->company_id,'user_id'=>$r->user()->id,'name'=>$file->getClientOriginalName(),'path'=>$path,'mime_type'=>$file->getMimeType(),'size'=>$file->getSize(),'entity_type'=>$r->entity_type,'entity_id'=>$r->entity_id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Archivo guardado','data'=>['id'=>$id]],201);}
    public function download(Request $r,int $id){$file=DB::table('documents')->where(['id'=>$id,'company_id'=>$r->user()->company_id])->firstOrFail();abort_unless(Storage::exists($file->path),404);return Storage::download($file->path,$file->name);}
    public function backups(Request $r){return response()->json(['success'=>true,'data'=>DB::table('backup_records')->where(fn($q)=>$q->whereNull('company_id')->orWhere('company_id',$r->user()->company_id))->latest()->get()]);}
    public function backup(Request $r){$filename='deurstore-'.now()->format('Ymd-His').'.sql';$relative='backups/'.$filename;$full=Storage::path($relative);if(!is_dir(dirname($full)))mkdir(dirname($full),0775,true);$error=\App\Support\DatabaseDump::dump($full);$code=$error?1:0;$status=$code===0?'completed':'failed';$id=DB::table('backup_records')->insertGetId(['company_id'=>$r->user()->company_id,'user_id'=>$r->user()->id,'filename'=>$filename,'path'=>$relative,'size'=>file_exists($full)?filesize($full):0,'type'=>'manual','status'=>$status,'error'=>$error?mb_substr($error,0,500):null,'created_at'=>now(),'updated_at'=>now()]);abort_if($code!==0,500,'No se pudo crear el respaldo');return response()->json(['success'=>true,'message'=>'Respaldo creado','data'=>['id'=>$id,'filename'=>$filename]],201);}
    public function downloadBackup(Request $r,int $id){$row=DB::table('backup_records')->where('id',$id)->firstOrFail();abort_unless(Storage::exists($row->path),404);return Storage::download($row->path,$row->filename);}
    public function restoreBackup(Request $r,int $id){$d=$r->validate(['password'=>'required','confirmation'=>'required|in:RESTAURAR']);abort_unless(Hash::check($d['password'],$r->user()->password),422,'Contraseña incorrecta');$row=DB::table('backup_records')->where(['id'=>$id,'company_id'=>$r->user()->company_id,'status'=>'completed'])->firstOrFail();abort_unless(Storage::exists($row->path),404,'El respaldo no existe');$error=\App\Support\DatabaseDump::restore(Storage::path($row->path));if($error)report(new \RuntimeException($error));abort_if($error!==null,500,'No se pudo restaurar el respaldo');return response()->json(['success'=>true,'message'=>'Base de datos restaurada correctamente']);}
    public function backupSchedules(Request $r){return response()->json(['success'=>true,'data'=>DB::table('backup_schedules')->where('company_id',$r->user()->company_id)->get()]);}
    public function saveBackupSchedule(Request $r){$d=$r->validate(['frequency'=>'required|in:daily,weekly,monthly','run_at'=>'required','retention_days'=>'required|integer|min:1|max:365','active'=>'boolean']);$next=match($d['frequency']){'daily'=>now()->addDay(),'weekly'=>now()->addWeek(),'monthly'=>now()->addMonth()};$id=DB::table('backup_schedules')->updateOrInsert(['company_id'=>$r->user()->company_id],$d+['user_id'=>$r->user()->id,'next_run_at'=>$next,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Programación guardada']);}
    public function status(Request $r){\App\Support\PlatformAccess::authorize($r->user());return response()->json(['success'=>true,'data'=>['php'=>PHP_VERSION,'laravel'=>app()->version(),'environment'=>app()->environment(),'database'=>DB::connection()->getDriverName().' '.DB::connection()->getPdo()->getAttribute(\PDO::ATTR_SERVER_VERSION),'queue_failed'=>DB::table('failed_jobs')->count(),'cache_driver'=>config('cache.default'),'disk_free'=>disk_free_space(storage_path()),'disk_total'=>disk_total_space(storage_path()),'time'=>now()->toIso8601String()]]);}
    public function optimize(Request $r){\App\Support\PlatformAccess::authorize($r->user());Artisan::call('optimize:clear');Artisan::call('config:cache');return response()->json(['success'=>true,'message'=>'Caché limpiada y configuración optimizada']);}
    public function logs(Request $r){\App\Support\PlatformAccess::authorize($r->user());$file=storage_path('logs/laravel.log');$content=file_exists($file)?file_get_contents($file):'';return response()->json(['success'=>true,'data'=>['content'=>substr($content,-50000)]]);}
    public function clearCache(Request $r){\App\Support\PlatformAccess::authorize($r->user());Artisan::call('optimize:clear');return response()->json(['success'=>true,'message'=>'Cachés eliminadas']);}
    public function maintenanceMode(Request $r){\App\Support\PlatformAccess::authorize($r->user());$d=$r->validate(['enabled'=>'required|boolean']);if($d['enabled']){Artisan::call('down',['--secret'=>'deurstore-admin','--render'=>'errors::503']);}else Artisan::call('up');return response()->json(['success'=>true,'message'=>$d['enabled']?'Modo mantenimiento activado':'Sistema reactivado','data'=>['enabled'=>$d['enabled'],'secret'=>$d['enabled']?'deurstore-admin':null]]);}
    public function failedJobs(Request $r){\App\Support\PlatformAccess::authorize($r->user());return response()->json(['success'=>true,'data'=>DB::table('failed_jobs')->latest('failed_at')->limit(100)->get()]);}
    public function retryJobs(Request $r){\App\Support\PlatformAccess::authorize($r->user());Artisan::call('queue:retry',['id'=>['all']]);return response()->json(['success'=>true,'message'=>'Trabajos fallidos enviados nuevamente a la cola']);}
    private function spreadsheetXml(array$rows,string$title):string{$headers=$rows?array_keys($rows[0]):[];$cell=fn($v)=>'<Cell><Data ss:Type="String">'.htmlspecialchars(is_array($v)?json_encode($v):((string)$v),ENT_XML1).'</Data></Cell>';$xml='<?xml version="1.0" encoding="UTF-8"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="'.htmlspecialchars(substr($title,0,31),ENT_XML1).'"><Table>';$xml.='<Row>'.implode('',array_map($cell,$headers)).'</Row>';foreach($rows as$row)$xml.='<Row>'.implode('',array_map($cell,array_values($row))).'</Row>';return$xml.'</Table></Worksheet></Workbook>';}
    private function simplePdf(string$title,array$rows):string{$lines=[$title,'Generado: '.now()->format('d/m/Y H:i')];if($rows){$headers=array_keys($rows[0]);$lines[]=implode(' | ',$headers);foreach(array_slice($rows,0,200)as$row)$lines[]=implode(' | ',array_map(fn($v)=>substr(preg_replace('/\s+/',' ',is_array($v)?json_encode($v):(string)$v),0,90),$row));}$content="BT /F1 9 Tf 36 800 Td 12 TL ";foreach($lines as$i=>$line){$safe=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],iconv('UTF-8','Windows-1252//TRANSLIT',$line));$content.=($i?'T* ':'')."({$safe}) Tj ";} $content.="ET";$objects=["1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj","2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj","3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >> endobj","4 0 obj << /Length ".strlen($content)." >> stream\n{$content}\nendstream endobj","5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj"];$pdf="%PDF-1.4\n";$offset=[0];foreach($objects as$o){$offset[]=strlen($pdf);$pdf.=$o."\n";}$xref=strlen($pdf);$pdf.="xref\n0 ".(count($objects)+1)."\n0000000000 65535 f \n";foreach(array_slice($offset,1)as$off)$pdf.=sprintf("%010d 00000 n \n",$off);return$pdf."trailer << /Size ".(count($objects)+1)." /Root 1 0 R >>\nstartxref\n{$xref}\n%%EOF";}
}
